1	const PROCESSING_FEE = 5;
2	
3	export type Item = {
4	  type: string;
5	  material?: string;
6	  enchantment?: number;
7	  cursed?: boolean;
8	};
9	
10	export type Step = {
11	  op: string;
12	  items: Item[];
13	};
14	
15	export type Customer = {
16	  yearsWithMHPCO: number;
17	};
18	
19	export type Scenario = {
20	  customer: Customer;
21	  steps: Step[];
22	};
23	
24	export type StepResult = {
25	  premium: number;
26	};
27	
28	export type ScenarioResults = {
29	  results: StepResult[];
30	};
31	
32	const BASE_PREMIUMS: Record<string, number> = {
33	  sword: 100,
34	  amulet: 60,
35	  staff: 80,
36	  potion: 40,
37	  rune: 25,
38	  moonstone: 25,
39	};
40	
41	// Percentages are applied as `amount * percent / 100` rather than
42	// `amount * 1.percent`, so that integer amounts stay exact: 100 * 1.1 is
43	// 110.00000000000001 in binary floating point, while 100 * 10 / 100 is 10.
44	const percentOf = (amount: number, percent: number): number =>
45	  (amount * percent) / 100;
46	
47	const basePremium = (item: Item): number => BASE_PREMIUMS[item.type];
48	
49	const BLOCK_SIZE = 3;
50	const BLOCK_BASE_PREMIUM = 60;
51	
52	// Items of the same type are priced together, so a policy is partitioned into
53	// same-type groups before any group pricing rule is applied.
54	const groupByType = (items: Item[]): Item[][] => {
55	  const groupsByType = new Map<string, Item[]>();
56	  for (const item of items) {
57	    const alike = groupsByType.get(item.type) ?? [];
58	    alike.push(item);
59	    groupsByType.set(item.type, alike);
60	  }
61	  return [...groupsByType.values()];
62	};
63	
64	const sumOf = <T>(values: T[], amount: (value: T) => number): number =>
65	  values.reduce((total, value) => total + amount(value), 0);
66	
67	// A building block of exactly 3 alike components is offered at a flat rate.
68	const groupBasePremium = (alike: Item[]): number =>
69	  alike.length === BLOCK_SIZE
70	    ? BLOCK_BASE_PREMIUM
71	    : sumOf(alike, basePremium);
72	
73	const itemsBasePremium = (items: Item[]): number =>
74	  sumOf(groupByType(items), groupBasePremium);
75	
76	const CURSE_SURCHARGE_PERCENT = 50;
77	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
78	const HIGH_ENCHANTMENT_LEVEL = 5;
79	
80	const isCursed = (item: Item): boolean => item.cursed === true;
81	
82	const isHighlyEnchanted = (item: Item): boolean =>
83	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
84	
85	// Each rule charges its percent of the affected item's own base premium.
86	type ItemSurchargeRule = {
87	  applies: (item: Item) => boolean;
88	  percent: number;
89	};
90	
91	const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
92	  { applies: isCursed, percent: CURSE_SURCHARGE_PERCENT },
93	  { applies: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
94	];
95	
96	// Item-specific surcharges apply to the base premium of the affected item.
97	// Several can apply to the same item, so every matching rule is summed.
98	const itemSurcharges = (item: Item): number => {
99	  const base = basePremium(item);
100	  return sumOf(
101	    ITEM_SURCHARGE_RULES.filter((rule) => rule.applies(item)),
102	    (rule) => percentOf(base, rule.percent),
103	  );
104	};
105	
106	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
107	const LOYALTY_DISCOUNT_PERCENT = 20;
108	const LOYALTY_YEARS = 2;
109	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
110	
111	const isLongStanding = (customer: Customer): boolean =>
112	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
113	
114	// Policy-wide modifiers adjust the policy base; item-specific surcharges are
115	// computed against each item's own unmodified base. Both are ADDITIVE against
116	// the base rather than compounding, so they are summed side by side and never
117	// nested inside one another. Discounts are negative percentages.
118	//
119	// Each modifier is written as its own percent-of-the-policy-base summand, so
120	// adding one never changes how the others are computed.
121	const policyModifiers = (
122	  policyBase: number,
123	  customer: Customer,
124	  priorContracts: number,
125	): number => {
126	  const firstInsurance = percentOf(policyBase, FIRST_INSURANCE_SURCHARGE_PERCENT);
127	  const loyalty = isLongStanding(customer)
128	    ? -percentOf(policyBase, LOYALTY_DISCOUNT_PERCENT)
129	    : 0;
130	  const followUp =
131	    priorContracts > 0
132	      ? -percentOf(policyBase, FOLLOW_UP_DISCOUNT_PERCENT)
133	      : 0;
134	  return firstInsurance + loyalty + followUp;
135	};
136	
137	const policyPremium = (
138	  items: Item[],
139	  customer: Customer,
140	  priorContracts: number,
141	): number => {
142	  const policyBase = itemsBasePremium(items);
143	  return (
144	    policyBase +
145	    policyModifiers(policyBase, customer, priorContracts) +
146	    sumOf(items, itemSurcharges)
147	  );
148	};
149	
150	// Amounts are rounded in the MHPCO's favor: premiums round up.
151	const roundPremium = (amount: number): number => Math.ceil(amount);
152	
153	const quote = (
154	  step: Step,
155	  customer: Customer,
156	  priorContracts: number,
157	): StepResult => ({
158	  premium: roundPremium(
159	    PROCESSING_FEE + policyPremium(step.items, customer, priorContracts),
160	  ),
161	});
162	
163	export const runScenario = (scenario: Scenario): ScenarioResults => ({
164	  results: scenario.steps.map((step, index) =>
165	    quote(step, scenario.customer, index),
166	  ),
167	});
